    40  /* zip_discard:
    41     frees the space allocated to a zipfile struct, and closes the
    42     corresponding file. */
    43
    44  void
    45  zip_discard(zip_t *za) {
    46      zip_uint64_t i;
    47
    48      if (za == NULL)
    49          return;
    50
    51      if (za->src) {
    52          zip_source_close(za->src);
    53          zip_source_free(za->src);
    54      }
    55
    56      free(za->default_password);
    57      _zip_string_free(za->comment_orig);
    58      _zip_string_free(za->comment_changes);
    59
    60      _zip_hash_free(za->names);
    61
    62      if (za->entry) {
    63          for (i = 0; i < za->nentry; i++)
    64              _zip_entry_finalize(za->entry + i);
    65          free(za->entry);
    66      }
    67
    68      for (i = 0; i < za->nopen_source; i++) {
    69          _zip_source_invalidate(za->open_source[i]);
    70      }
    71      free(za->open_source);
    72
    73      _zip_progress_free(za->progress);
    74
    75      zip_error_fini(&za->error);
    76
    77      free(za);
    78
    79      return;
    80  }
